-- Agenda Uninorte: amplía la agenda a 2026–2028 y carga las tareas de 2026 (Calendario 2026 V1.1).
-- Pégalo completo en Supabase → SQL Editor → Run. Se puede correr más de una vez sin duplicar nada.

alter table public.tareas drop constraint if exists tareas_fecha_check;
alter table public.tareas add constraint tareas_fecha_check check (fecha between '2026-01-01' and '2028-12-31');
alter table public.tareas drop constraint if exists tareas_nombre_check;
alter table public.tareas add constraint tareas_nombre_check check (char_length(nombre) between 1 and 300);
alter table public.tareas drop constraint if exists tareas_ubicacion_check;
alter table public.tareas add constraint tareas_ubicacion_check check (char_length(ubicacion) <= 200);

on conflict (id) do nothing;
